using BmsDesktop.Infrastructure;
using Npgsql;
namespace BmsDesktop.Marketing;
public sealed class AdditionalMeatService { private readonly Database _db; public AdditionalMeatService(Database db)=>_db=db; public async Task<Guid> AddAsync(Guid cycle,Guid? supplier,DateOnly date,int birds,decimal kg,decimal actualPrice,string notes){if(birds<0||kg<0||actualPrice<0)throw new ArgumentException("Data Tambah Daging tidak valid.");await using var cn=await _db.OpenAsync();await using var c=new NpgsqlCommand("insert into additional_meat_purchases(id,cycle_id,supplier_id,purchase_date,bird_qty,weight_kg,actual_unit_price,notes) values(@id,@c,@d,@dt,@b,@w,@p,@n)",cn);var id=Guid.NewGuid();c.Parameters.AddWithValue("id",id);c.Parameters.AddWithValue("c",cycle);c.Parameters.AddWithValue("d",(object?)supplier??DBNull.Value);c.Parameters.AddWithValue("dt",date.ToDateTime(TimeOnly.MinValue));c.Parameters.AddWithValue("b",birds);c.Parameters.AddWithValue("w",kg);c.Parameters.AddWithValue("p",actualPrice);c.Parameters.AddWithValue("n",notes??"");await c.ExecuteNonQueryAsync();return id;} }
